import { afterEach, expect, it, vi } from 'vitest';
import { readFileSync, promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  createMemoryRuntimeStore,
  createRuntime,
  defineWorkflow,
  hashRuntimeValue,
  type RuntimeValue,
  type WorkflowRun,
} from '../../../domains/engine/runtime.js';
import {
  defineNativeWorkflowApplication,
  nativeSdkApplicationForRun,
} from '../../../domains/comet-native/native-sdk-application.js';
import * as definitions from '../../../domains/comet-native/native-sdk-definition.js';
import { createNativePortableState } from '../../../domains/comet-native/native-portable-state.js';

const application = defineNativeWorkflowApplication();
const currentHash = hashRuntimeValue(defineWorkflow(application.workflow));
const legacy = definitions.nativeSdkLegacyDefinitions(application.workflow);
const reference = (hash: string) => ({ workflow: { id: 'comet-native', version: '1', hash } });
const originalV4 = JSON.parse(
  readFileSync('test/fixtures/native-v4-internal-actions/workflow.json', 'utf8'),
);

it.each(definitions.nativeSdkLegacyDefinitions(originalV4).map((workflow, index) => ({ workflow, index })))(
  'retains the original v4 compatibility definition $index after internal step removal',
  ({ workflow }) => {
    const hash = hashRuntimeValue(defineWorkflow(workflow));
    const selected = nativeSdkApplicationForRun({
      workflow: { id: 'comet-native', version: '4', hash },
    });
    expect(hashRuntimeValue(defineWorkflow(selected.workflow))).toBe(hash);
  },
);

it('omits internal result-transfer Actions from new v4 while selecting the original v4 definition', () => {
  const compact = defineNativeWorkflowApplication('4');
  expect(compact.workflow.steps).not.toHaveProperty('shape.revalidate');
  expect(compact.workflow.steps).not.toHaveProperty('verify.revalidate');
  const hash = hashRuntimeValue(defineWorkflow(originalV4));
  const selected = nativeSdkApplicationForRun({
    workflow: { id: 'comet-native', version: '4', hash },
  });
  expect(hashRuntimeValue(defineWorkflow(selected.workflow))).toBe(hash);
  expect(selected.workflow.steps).toHaveProperty('shape.revalidate');
  expect(selected.workflow.steps).toHaveProperty('verify.revalidate');
  expect(selected.transitionHandler).not.toBe(compact.transitionHandler);
});

it.each(['pending', 'unknown'] as const)(
  'continues the original v4 Shape Action after compact definitions ship (%s)',
  async (status) => {
    const root = await fs.mkdtemp(path.join(os.tmpdir(), 'native-v4-original-shape-'));
    try {
      const selected = nativeSdkApplicationForRun({
        workflow: {
          id: 'comet-native', version: '4',
          hash: hashRuntimeValue(defineWorkflow(originalV4)),
        },
      });
      const store = createMemoryRuntimeStore<WorkflowRun>();
      const runtime = createRuntime({
        ...selected, store, workflows: [selected.workflow],
        transitionHandlers: [selected.transitionHandler],
      });
      let run = await runtime.start({
        runId: 'original-v4-shape', workflow: { id: 'comet-native', version: '4' },
        input: { name: 'original-v4-shape', artifactRootRef: 'docs' },
        initialState: createNativePortableState({ name: 'original-v4-shape', language: 'en' }) as unknown as RuntimeValue,
      });
      const context = { projectRoot: root, requestId: 'original-shape' };
      const proposal = {
        specChanges: [], children: null,
        acceptance: [{ id: 'A1', source: 'brief.md', text: 'Preserve the approved behavior.' }],
      };
      const prepared = run.actions.at(-1)!;
      run = await runtime.claim({
        runId: run.runId, actionId: prepared.id, executorId: 'native-host',
        attempt: prepared.attempt, inputHash: prepared.inputHash,
        claimToken: 'original-prepare', context,
      });
      run = await runtime.recordOutcome({
        runId: run.runId,
        outcome: {
          actionId: prepared.id, attempt: prepared.attempt, inputHash: prepared.inputHash,
          claimToken: 'original-prepare', outcomeId: 'original-prepare',
          status: 'succeeded', output: proposal,
        }, context,
      });
      const wait = run.waits.at(-1)!;
      run = await runtime.resolveWait({
        runId: run.runId, waitId: wait.id, proposalHash: wait.proposalHash,
        decisionId: 'original-approval', choice: 'approved', context,
      });
      const original = run.actions.at(-1)!;
      expect(original.stepId).toBe('shape.revalidate');
      if (status === 'unknown') run = await runtime.claim({
        runId: run.runId, actionId: original.id, executorId: 'native-host',
        attempt: original.attempt, inputHash: original.inputHash,
        claimToken: 'original-revalidation', context,
      });
      if (status === 'unknown') run = await runtime.markUnknown({
        runId: run.runId, actionId: original.id, attempt: original.attempt,
        reason: 'The original host stopped before submitting the known Shape result.',
      });
      const restored = nativeSdkApplicationForRun(run);
      const reader = createRuntime({
        ...restored, store, workflows: [restored.workflow],
        transitionHandlers: [restored.transitionHandler],
      });
      if (status === 'pending') await reader.claim({
        runId: run.runId, actionId: original.id, executorId: 'native-host',
        attempt: original.attempt, inputHash: original.inputHash,
        claimToken: 'original-revalidation', context,
      });
      const recovered = await reader.recordOutcome({
        runId: run.runId,
        outcome: {
          actionId: original.id, attempt: original.attempt, inputHash: original.inputHash,
          claimToken: 'original-revalidation', outcomeId: 'original-revalidation',
          status: 'succeeded', output: proposal,
        }, context,
      });
      expect(recovered.runId).toBe(run.runId);
      expect(recovered.waits).toEqual(run.waits);
      expect(recovered.actions.find((action) => action.id === prepared.id)).toEqual(run.actions[0]);
      expect(recovered.actions.find((action) => action.id === original.id)?.status).toBe('succeeded');
      expect(recovered.actions.at(-1)).toMatchObject({ stepId: 'build.builder', status: 'pending' });
      expect(recovered.actions.filter((action) => action.stepId === 'shape.prepare')).toHaveLength(1);
    } finally {
      await fs.rm(root, { recursive: true, force: true });
    }
  },
);
it('allows missing Builder raw receipts only for the exact known legacy definitions', () => {
  expect(new Set(legacy.map((workflow) => hashRuntimeValue(defineWorkflow(workflow))))).toEqual(
    new Set(definitions.NATIVE_SDK_LEGACY_BUILDER_INPUT_HASHES),
  );
  expect(definitions.NATIVE_SDK_LEGACY_BUILDER_INPUT_HASHES).not.toContain(currentHash);
});
afterEach(() => vi.restoreAllMocks());

it('recognizes the persisted builtin definition before integration repair recovery', () => {
  const hash = '42c3944e15a25dc0cd179212587049deef1052f47d9c09d2248c2a8de936ec19';
  const selected = nativeSdkApplicationForRun(reference(hash), application);
  expect(hashRuntimeValue(defineWorkflow(selected.workflow))).toBe(hash);
});

it('returns the exact current application without constructing legacy definitions', () => {
  const probe = vi.spyOn(definitions, 'nativeSdkLegacyDefinitions');
  expect(nativeSdkApplicationForRun(reference(currentHash), application)).toBe(application);
  expect(probe).not.toHaveBeenCalled();
});

it.each(legacy.map((workflow, index) => ({ workflow, index })))(
  'retains known legacy definition $index and its transition adapter',
  ({ workflow }) => {
    const hash = hashRuntimeValue(defineWorkflow(workflow));
    const probe = vi.spyOn(definitions, 'nativeSdkLegacyDefinitions');
    const selected = nativeSdkApplicationForRun(reference(hash), application);
    expect(probe).toHaveBeenCalledOnce();
    expect(hashRuntimeValue(defineWorkflow(selected.workflow))).toBe(hash);
    expect(selected.transitionHandler).not.toBe(application.transitionHandler);
  },
);

it('keeps a missing Run on the original selection path', () => {
  const probe = vi.spyOn(definitions, 'nativeSdkLegacyDefinitions');
  expect(nativeSdkApplicationForRun(null, application)).toBe(application);
  expect(probe).toHaveBeenCalledOnce();
});

it('leaves an unknown hash rejected by Runtime inspection', async () => {
  const runtime = createRuntime({
    ...application,
    store: createMemoryRuntimeStore<WorkflowRun>(),
    workflows: [application.workflow],
    transitionHandlers: [application.transitionHandler],
  });
  const run = await runtime.start({
    runId: 'definition-selection',
    workflow: { id: 'comet-native', version: '1' },
    input: { name: 'definition-selection', artifactRootRef: 'docs' },
    initialState: createNativePortableState({
      name: 'definition-selection',
      language: 'en',
    }) as unknown as RuntimeValue,
  });
  const unknown = 'f'.repeat(64);
  const corrupted = {
    ...run,
    workflow: { ...run.workflow, hash: unknown },
    definitionHashes: Object.fromEntries(
      Object.keys(run.definitionHashes).map((key) => [key, unknown]),
    ),
  };
  const probe = vi.spyOn(definitions, 'nativeSdkLegacyDefinitions');
  const selected = nativeSdkApplicationForRun(corrupted, application);
  expect(probe).toHaveBeenCalledOnce();
  const reader = createRuntime({
    ...selected,
    store: { read: async () => corrupted, compareAndSwap: async () => false },
    workflows: [selected.workflow],
    transitionHandlers: [selected.transitionHandler],
  });
  await expect(reader.inspect(run.runId)).rejects.toMatchObject({ code: 'WORKFLOW_CHANGED' });
});

it('keeps canonical hashes and legacy selection when reusing a normalized builtin', () => {
  const compiled = { ...application, workflow: defineWorkflow(application.workflow) };
  expect(nativeSdkApplicationForRun(reference(currentHash), compiled)).toBe(compiled);
  for (const workflow of legacy) {
    const hash = hashRuntimeValue(defineWorkflow(workflow));
    const selected = nativeSdkApplicationForRun(reference(hash), compiled);
    expect(hashRuntimeValue(defineWorkflow(selected.workflow))).toBe(hash);
    expect(selected.transitionHandler).not.toBe(compiled.transitionHandler);
  }
  const fresh = defineNativeWorkflowApplication();
  fresh.workflow.steps['shape.prepare'].ref = 'changed';
  expect(definitions.nativeSdkMatchesRun(fresh.workflow, reference(currentHash))).toBe(false);
  expect(definitions.nativeSdkMatchesRun(compiled.workflow, reference(currentHash))).toBe(true);
  expect(defineNativeWorkflowApplication().workflow.steps['shape.prepare'].ref).not.toBe('changed');
});

